#include <errno.h>
#include <string.h>
#include <zephyr/sys/min_heap.h>

typedef __typeof__(_Generic((&min_heap_push),
	int (*)(struct min_heap *, const void *): (const void *)0,
	default: (void *)0)) z_min_heap_item_t;

int z_min_heap_push_impl(struct min_heap *heap, z_min_heap_item_t item);

int min_heap_push(struct min_heap *heap, z_min_heap_item_t item)
{
	if (heap->size >= heap->capacity) {
		return -ENOMEM;
	}

	return z_min_heap_push_impl(heap, item);
}

